/* Dash system runtime: the clock as Unix seconds and as days, running a command and waiting, opening an icon,
   the program's path, the preferred language, the CPU and the FPU, library versions, the task's priority. */
#include <dos/dostags.h>
#include <workbench/startup.h>
#include <proto/wb.h>
#include <libraries/locale.h>
#include <proto/locale.h>
extern struct WBStartup *_WBenchMsg;
#ifndef _DASH_WB_PATH_DEF
#define _DASH_WB_PATH_DEF
/* A program started from the Workbench has no CLI and so no path: the shells of run_program and run_command
   would only find C:, and so would a Shell opened through C:WBRun (Workbench gives it its caller's path).
   They get a copy of the Workbench's own path, the one a double click gives (the new shell owns it).
   0 if the caller has a CLI: its path is copied as usual. */
static BPTR _dash_wb_path(void) {
    struct Process *wb;
    struct CommandLineInterface *cli;
    BPTR p, first = 0, *last = &first;
    if (((struct Process *)FindTask(NULL))->pr_CLI) return 0;
    Forbid();
    wb = (struct Process *)FindTask((CONST_STRPTR)"Workbench");
    cli = (wb && wb->pr_Task.tc_Node.ln_Type == NT_PROCESS) ? (struct CommandLineInterface *)BADDR(wb->pr_CLI) : NULL;
    if (cli)
        for (p = cli->cli_CommandDir; p; p = ((BPTR *)BADDR(p))[0]) {
            BPTR *node = (BPTR *)AllocVec(8, MEMF_PUBLIC | MEMF_CLEAR);   /* (as dos makes them: next, lock) */
            if (!node) break;
            node[1] = DupLock(((BPTR *)BADDR(p))[1]);
            *last = MKBADDR(node);
            last = &node[0];
        }
    Permit();
    return first;
}
#endif

static LONG _dash_time_unix(void) {
    struct DateStamp d;
    DateStamp(&d);
    return 252460800L + d.ds_Days * 86400L + d.ds_Minute * 60L + d.ds_Tick / 50;   /* 1978 - 1970 */
}

static LONG _dash_clock_days(void) {
    struct DateStamp d;
    DateStamp(&d);
    return d.ds_Days;
}

static STRPTR _dash_build_date(void) {
    static const char months[] = "JanFebMarAprMayJunJulAugSepOctNovDec";
    static char d[11];
    const char *s = __DATE__;          /* "Oct 28 2026" */
    int i, m = 1;
    for (i = 0; i < 12; i++)
        if (!strncmp(months + 3 * i, s, 3)) m = i + 1;
    sprintf(d, "%.4s-%02d-%c%c", s + 7, m, s[4] == ' ' ? '0' : s[4], s[5]);
    return (STRPTR)d;
}

static void _dash_console_flush(void) {
    if (Output()) Flush(Output());
}

static LONG _dash_run_command(STRPTR command) {
    BPTR nil, path;
    LONG rc;
    if (!command || !*command) return -1;
    if (!(nil = Open((CONST_STRPTR)"NIL:", MODE_OLDFILE))) return -1;
    _dash_console_flush();          /* what Print left in the buffer goes before the command's output */
    path = _dash_wb_path();         /* (from the Workbench: its path) */
    /* (waiting for it, System does not close them) */
    rc = SystemTags(command, SYS_Input, nil, SYS_Output, Output() ? Output() : nil, NP_StackSize, 16384,
                    path ? NP_Path : TAG_IGNORE, path, TAG_DONE);
    Close(nil);
    return rc;
}

/* Ends the program now with that return code, after the usual cleanup (dashgit, scripts: 5, 10, 20) */
static void _dash_program_exit(LONG rc) {
    _dash_exit((int)rc);
}

static BOOL _dash_wb_open(STRPTR path) {
    struct Library *WorkbenchBase;
    BOOL r = FALSE;
    if (!path || !*path) return FALSE;
    if ((WorkbenchBase = OpenLibrary((CONST_STRPTR)"workbench.library", 44))) {
        r = OpenWorkbenchObjectA(path, NULL);
        CloseLibrary(WorkbenchBase);
    }
    return r;
}

static STRPTR _dash_program_path(void) {
    char dir[300], name[108];
    struct Process *p = (struct Process *)FindTask(NULL);
    dir[0] = 0;
    name[0] = 0;
    if (!GetProgramDir() || !NameFromLock(GetProgramDir(), (STRPTR)dir, 200)) return _dash_str_dup((STRPTR)"", TRUE);
    if (p->pr_CLI) GetProgramName((STRPTR)name, sizeof(name));
    else if (_WBenchMsg && _WBenchMsg->sm_NumArgs > 0) strncpy(name, (char *)_WBenchMsg->sm_ArgList[0].wa_Name, sizeof(name) - 1);
    else if (p->pr_Task.tc_Node.ln_Name) strncpy(name, p->pr_Task.tc_Node.ln_Name, sizeof(name) - 1);
    name[sizeof(name) - 1] = 0;
    AddPart((STRPTR)dir, FilePart((STRPTR)name), sizeof(dir));
    return _dash_str_dup((STRPTR)dir, TRUE);
}

static STRPTR _dash_locale_language(void) {
    /* (a base of its own: the program may not use locale.library) */
    struct LocaleBase *LocaleBase = (struct LocaleBase *)OpenLibrary((CONST_STRPTR)"locale.library", 38);
    char lang[64];
    lang[0] = 0;
    if (LocaleBase) {
        struct Locale *loc = OpenLocale(NULL);
        if (loc) {
            if (loc->loc_PrefLanguages[0]) {
                strncpy(lang, (char *)loc->loc_PrefLanguages[0], sizeof(lang) - 1);
                lang[sizeof(lang) - 1] = 0;
            }
            CloseLocale(loc);
        }
        CloseLibrary((struct Library *)LocaleBase);
    }
    return _dash_str_dup((STRPTR)lang, TRUE);
}

static LONG _dash_cpu_model(void) {
    UWORD f = SysBase->AttnFlags;
    if (f & (1 << 7)) return 68060;          /* AFF_68060 */
    if (f & AFF_68040) return 68040;
    if (f & AFF_68030) return 68030;
    if (f & AFF_68020) return 68020;
    if (f & AFF_68010) return 68010;
    return 68000;
}

static LONG _dash_fpu_model(void) {
    UWORD f = SysBase->AttnFlags;
    if (f & AFF_FPU40) return (f & (1 << 7)) ? 68060 : 68040;
    if (f & AFF_68882) return 68882;
    if (f & AFF_68881) return 68881;
    return 0;
}

#include <graphics/gfxbase.h>
/* "AGA" con chips de AGA, "ECS" con Agnus o Denise de ECS, "OCS" si no (GfxBase->ChipRevBits0; un A1200 de
   FS-UAE da solo GFXF_AA_MLISA, sin Alice ni Lisa) */
static STRPTR _dash_chipset_model(void) {
    struct GfxBase *g = (struct GfxBase *)OpenLibrary((CONST_STRPTR)"graphics.library", 0);
    const char *c = "OCS";
    if (g) {
        if (g->ChipRevBits0 & (GFXF_AA_ALICE | GFXF_AA_LISA | GFXF_AA_MLISA)) c = "AGA";
        else if (g->ChipRevBits0 & (GFXF_HR_AGNUS | GFXF_HR_DENISE)) c = "ECS";
        CloseLibrary((struct Library *)g);
    }
    return _dash_str_dup((STRPTR)c, TRUE);
}

static LONG _dash_library_version(STRPTR name) {
    struct Library *l;
    LONG v;
    if (!name || !*name || !(l = OpenLibrary((CONST_STRPTR)name, 0))) return -1;
    v = l->lib_Version;
    CloseLibrary(l);
    return v;
}

static LONG _dash_library_revision(STRPTR name) {
    struct Library *l;
    LONG v;
    if (!name || !*name || !(l = OpenLibrary((CONST_STRPTR)name, 0))) return -1;
    v = l->lib_Revision;
    CloseLibrary(l);
    return v;
}

static LONG _dash_resident_version(STRPTR name) {
    struct Resident *r;
    if (!name || !*name || !(r = FindResident((CONST_STRPTR)name))) return -1;
    return r->rt_Version;
}

static LONG _dash_task_priority(LONG n) {
    if (n < -128) n = -128;
    if (n > 127) n = 127;
    return SetTaskPri(FindTask(NULL), n);
}

/* env_get(name): a variable of the program's Shell or of ENV: (GetVar, up to its first line end); "" without it.
   env_set(name, value, save): in ENV:, and with save also in ENVARC: (V39+) */
static STRPTR _dash_env_get(STRPTR name) {
    LONG size = 1024, n;
    STRPTR buf, r;
    if (!name || !*name) return _dash_str_dup((STRPTR)"", TRUE);
    for (;;) {
        if (!(buf = (STRPTR)AllocVec(size, MEMF_ANY))) return _dash_str_dup((STRPTR)"", TRUE);
        n = GetVar(name, buf, size, 0);
        if (n < size - 1 || size >= 262144) break;
        FreeVec(buf);          /* it may not have fitted */
        size *= 8;
    }
    if (n < 0) buf[0] = 0;
    r = _dash_str_dup(buf, TRUE);
    FreeVec(buf);
    return r;
}

/* The whole variable, all its lines (env_get stops at the first line end; lo pidió Forja), without the line end of
   the last one */
static STRPTR _dash_env_get_text(STRPTR name) {
    LONG size = 1024, n;
    STRPTR buf, r;
    if (!name || !*name) return _dash_str_dup((STRPTR)"", TRUE);
    for (;;) {
        if (!(buf = (STRPTR)AllocVec(size, MEMF_ANY))) return _dash_str_dup((STRPTR)"", TRUE);
        n = GetVar(name, buf, size, GVF_BINARY_VAR);
        if (n < size - 1 || size >= 4194304) break;
        FreeVec(buf);          /* it may not have fitted */
        size *= 8;
    }
    if (n < 0) n = 0;
    if (n > size - 1) n = size - 1;
    if (n > 0 && buf[n - 1] == '\n') n--;
    buf[n] = 0;
    r = _dash_str_dup(buf, TRUE);
    FreeVec(buf);
    return r;
}

/* The file of a global variable written here, not with SetVar: when another process was reading it (GetVar),
   SetVar of 3.1 wrote over it without cutting it ("libre" over "pidiendo" left "librendo"). MODE_NEWFILE is
   exclusive and empties it: while someone reads it, it is tried again each tick, a second at most */
static BOOL _dash_env_file(const char *dir, STRPTR name, STRPTR value, LONG len) {
    char path[300];
    BPTR f = 0;
    LONG k;
    BOOL ok;
    if (strlen((char *)name) > 250) return FALSE;
    sprintf(path, "%s%s", dir, (char *)name);
    for (k = 0; k < 50 && !(f = Open((CONST_STRPTR)path, MODE_NEWFILE)); k++) {
        if (IoErr() != ERROR_OBJECT_IN_USE) return FALSE;
        Delay(1);
    }
    if (!f) return FALSE;
    ok = Write(f, value, len) == len;
    Close(f);
    return ok;
}

static BOOL _dash_env_set(STRPTR name, STRPTR value, BOOL save) {
    LONG len;
    if (!name || !*name) return FALSE;
    if (!value) value = (STRPTR)"";
    len = strlen((char *)value);
    if (_dash_env_file("ENV:", name, value, len) && (!save || _dash_env_file("ENVARC:", name, value, len)))
        return TRUE;
    /* (ENV: or a drawer of the name that is not there: as before) */
    return SetVar(name, value, len, GVF_GLOBAL_ONLY | (save ? GVF_SAVE_VAR : 0)) != 0;
}


/* Dash Handler Runtime */
#include <dos/dosextens.h>
#include <dos/filehandler.h>
#include <exec/io.h>
#include <exec/errors.h>
#include <devices/trackdisk.h>
#include <devices/input.h>
#include <devices/inputevent.h>
#ifndef TD_READ64
#define TD_READ64 24
#define TD_WRITE64 25
#endif
#ifndef NSCMD_TD_READ64
#define NSCMD_TD_READ64 0xC000
#define NSCMD_TD_WRITE64 0xC001
#endif

/* Set before the program starts (./dash: _dash_start; --gcc: main) when it is a handler */
LONG _dash_hd_on = 0;
static struct DosPacket *_dash_hd_start;        /* the startup packet, until handler_ready answers it */
static LONG _dash_hd_cur;                       /* the last packet handler_wait gave, until it is answered */
static struct DeviceNode *_dash_hd_node;
static struct MsgPort *_dash_hd_port;           /* where the packets come (dn_Task): not pr_MsgPort, the DOS's own */
static LONG _dash_hd_startup;                   /* dn_Startup (a FileSysStartupMsg with Device=) */
static char _dash_hd_devname[32];
static BPTR _dash_hd_nilfh, _dash_hd_logfh, _dash_hd_oldout;
static struct DosList *_dash_hd_vols[8];
static struct IOExtTD *_dash_dev_ios[8];
static BOOL _dash_dev_atexit, _dash_hd_atexit;

static void _dash_hd_reply(LONG pkt, LONG res1, LONG res2) {
    struct DosPacket *p = (struct DosPacket *)pkt;
    struct MsgPort *to;
    if (!p) return;
    if (pkt == _dash_hd_cur) _dash_hd_cur = 0;
    to = p->dp_Port;
    p->dp_Res1 = res1;
    p->dp_Res2 = res2;
    p->dp_Port = _dash_hd_port ? _dash_hd_port : &((struct Process *)FindTask(NULL))->pr_MsgPort;
    PutMsg(to, p->dp_Link);
}

/* An error answer: -1 for READ, WRITE and SEEK (their result is a length or a position), DOSFALSE for the rest.
   ERROR_OBJECT_NOT_FOUND: ERROR_DEVICE_NOT_MOUNTED or ERROR_NO_DISK make the client's DOS open a requester
   ("insert volume") and wait */
static void _dash_hd_refuse(LONG pkt, LONG err) {
    LONG t = ((struct DosPacket *)pkt)->dp_Type;
    _dash_hd_reply(pkt, t == ACTION_READ || t == ACTION_WRITE || t == ACTION_SEEK ? -1 : DOSFALSE, err);
}

/* A disk went in or out: the Workbench looks at the volumes again (as FFS does) */
static void _dash_hd_diskevent(UBYTE cls) {
    struct MsgPort *mp = CreateMsgPort();
    struct IOStdReq *io;
    struct InputEvent ie;
    if (!mp) return;
    if ((io = (struct IOStdReq *)CreateIORequest(mp, sizeof(struct IOStdReq)))) {
        if (!OpenDevice((CONST_STRPTR)"input.device", 0, (struct IORequest *)io, 0)) {
            memset(&ie, 0, sizeof(ie));
            ie.ie_Class = cls;
            io->io_Command = IND_WRITEEVENT;
            io->io_Data = &ie;
            io->io_Length = sizeof(ie);
            DoIO((struct IORequest *)io);
            CloseDevice((struct IORequest *)io);
        }
        DeleteIORequest((struct IORequest *)io);
    }
    DeleteMsgPort(mp);
}

/* The end, however it comes (Stop, an error, Ctrl-C): in Forbid, nobody sends to the port any more (dn_Task and the
   volumes' dl_Task to 0: the volumes stay, as a disk taken out), what is left in it is answered with an error, and
   dn_SegList to 0, so that the DOS loads a clean copy on the next access (the globals of this one are spent; its
   code stays in memory: it cannot be unloaded from inside) */
static void _dash_hd_end(void) {
    struct Message *m;
    int i;
    if (_dash_hd_start) _dash_hd_reply((LONG)_dash_hd_start, DOSFALSE, ERROR_OBJECT_NOT_FOUND);
    _dash_hd_start = NULL;
    /* the packet it was doing when it ended (a runtime error): its client would wait for ever */
    if (_dash_hd_cur) _dash_hd_refuse(_dash_hd_cur, ERROR_OBJECT_NOT_FOUND);
    Forbid();
    if (_dash_hd_node) {
        _dash_hd_node->dn_Task = NULL;
        _dash_hd_node->dn_SegList = 0;
    }
    for (i = 0; i < 8; i++)
        if (_dash_hd_vols[i]) _dash_hd_vols[i]->dol_Task = NULL;
    if (_dash_hd_port) {
        while ((m = GetMsg(_dash_hd_port)))
            _dash_hd_refuse((LONG)m->mn_Node.ln_Name, ERROR_OBJECT_NOT_FOUND);
        DeleteMsgPort(_dash_hd_port);
        _dash_hd_port = NULL;
    }
    Permit();
    if (_dash_hd_oldout || _dash_hd_nilfh || _dash_hd_logfh) {
        Flush(Output());
        SelectOutput(_dash_hd_oldout);
        if (_dash_hd_logfh) Close(_dash_hd_logfh);
        if (_dash_hd_nilfh) Close(_dash_hd_nilfh);
        _dash_hd_logfh = _dash_hd_nilfh = 0;
    }
    _dash_out_nil = 0;
}

/* At the start of a handler (msg: what came to pr_MsgPort, the startup packet). 1 if it was one */
static LONG _dash_hd_begin(struct Message *msg) {
    UBYTE *b;
    LONG n;
    /* (a packet's message has it in ln_Name; a WBStartup, 0: started from the Workbench by mistake) */
    if (!_dash_hd_on || !msg || !msg->mn_Node.ln_Name) return 0;
    _dash_hd_start = (struct DosPacket *)msg->mn_Node.ln_Name;
    _dash_hd_startup = _dash_hd_start->dp_Arg2;
    _dash_hd_node = (struct DeviceNode *)BADDR(_dash_hd_start->dp_Arg3);
    if (_dash_hd_node && (b = (UBYTE *)BADDR(_dash_hd_node->dn_Name))) {
        n = b[0] < sizeof(_dash_hd_devname) ? b[0] : sizeof(_dash_hd_devname) - 1;
        memcpy(_dash_hd_devname, b + 1, n);
        _dash_hd_devname[n] = 0;
        if (n && _dash_hd_devname[n - 1] == ':') _dash_hd_devname[n - 1] = 0;
    }
    if (!_dash_hd_atexit) _dash_hd_atexit = _dash_atexit(_dash_hd_end) == 0;
    /* without a console: Print goes nowhere until handler_log (NIL: is the DOS's own: no packets) */
    if ((_dash_hd_nilfh = Open((CONST_STRPTR)"NIL:", MODE_NEWFILE))) {
        _dash_hd_oldout = SelectOutput(_dash_hd_nilfh);
        _dash_out_nil = _dash_hd_nilfh;
    }
    if (!(_dash_hd_port = CreateMsgPort())) {
        _dash_hd_reply((LONG)_dash_hd_start, DOSFALSE, ERROR_NO_FREE_STORE);
        _dash_hd_start = NULL;
        _dash_exit(20);
    }
    /* the clients' packets wait in the port of their own from now on, until handler_wait */
    if (_dash_hd_node) _dash_hd_node->dn_Task = _dash_hd_port;
    return 1;
}

/* handler_ready(ok, err): the answer to the startup packet */
static void _dash_hd_ready(LONG ok, LONG err) {
    LONG p = (LONG)_dash_hd_start;
    if (_dash_hd_on && !_dash_hd_node)   /* (started from the Shell or the Workbench) */
        _dash_fail("este programa es un handler de DOS: se monta con Mount", NULL);
    if (!p) return;
    _dash_hd_start = NULL;
    if (!ok && _dash_hd_node) _dash_hd_node->dn_Task = NULL;
    _dash_hd_reply(p, ok ? DOSTRUE : DOSFALSE, ok ? 0 : err);
}

/* The next packet (its DosPacket), waiting for it; 0 with Ctrl-C (or if the program is not a handler) */
static LONG _dash_hd_wait(void) {
    struct Message *m;
    if (!_dash_hd_port) return 0;
    for (;;) {
        if ((m = GetMsg(_dash_hd_port))) return _dash_hd_cur = (LONG)m->mn_Node.ln_Name;
        if (_dash_hd_logfh) Flush(_dash_hd_logfh);   /* the log, up to date while it waits */
        if (Wait((1UL << _dash_hd_port->mp_SigBit) | SIGBREAKF_CTRL_C) & SIGBREAKF_CTRL_C) return 0;
    }
}

static LONG _dash_hd_poll(void) {
    struct Message *m = _dash_hd_port ? GetMsg(_dash_hd_port) : NULL;
    return m ? _dash_hd_cur = (LONG)m->mn_Node.ln_Name : 0;
}

/* Print to this file from now on (and the runtime's errors); FALSE if it does not open */
/* (emptied, then open in shared mode: others can read it while the handler runs) */
static BOOL _dash_hd_log(STRPTR path) {
    BPTR fh = path ? Open((CONST_STRPTR)path, MODE_NEWFILE) : 0;
    if (!fh) return FALSE;
    Close(fh);
    if (!(fh = Open((CONST_STRPTR)path, MODE_READWRITE))) return FALSE;
    if (!_dash_hd_oldout && !_dash_hd_nilfh) _dash_hd_oldout = Output();
    Flush(Output());
    SelectOutput(fh);
    if (_dash_hd_logfh) Close(_dash_hd_logfh);
    _dash_hd_logfh = fh;
    _dash_out_nil = 0;
    if (!_dash_hd_atexit) _dash_hd_atexit = _dash_atexit(_dash_hd_end) == 0;
    return TRUE;
}

static STRPTR _dash_hd_name(void) {
    return _dash_str_dup((STRPTR)_dash_hd_devname, TRUE);
}

/* A BSTR (its BPTR) as a text */
static STRPTR _dash_bstr_text(LONG b) {
    UBYTE *s = (UBYTE *)BADDR(b);
    STRPTR t;
    if (!s) return _dash_str_dup((STRPTR)"", TRUE);
    t = _dash_str_alloc(s[0], TRUE);
    if (t && s[0]) memcpy(t, s + 1, s[0]);
    return t;
}

/* text as a BSTR at addr, in max bytes (a 0 after it when it fits) */
static void _dash_bstr_put(LONG addr, STRPTR text, LONG max) {
    UBYTE *d = (UBYTE *)addr;
    ULONG n = text ? strlen((char *)text) : 0;
    if (!d || max < 1) return;
    if (n > (ULONG)max - 1) n = max - 1;
    if (n > 255) n = 255;
    d[0] = (UBYTE)n;
    if (n) memcpy(d + 1, text, n);
    if (n + 1 < (ULONG)max) d[n + 1] = 0;
}

/* A volume of this handler in the DOS list (and the Workbench told); its DosList, 0 if it cannot */
static LONG _dash_hd_vol_add(STRPTR name, LONG type) {
    struct DosList *dl;
    LONG ok, i;
    if (!name || !(dl = MakeDosEntry((CONST_STRPTR)name, DLT_VOLUME))) return 0;
    dl->dol_Task = _dash_hd_port;
    DateStamp(&dl->dol_misc.dol_volume.dol_VolumeDate);
    dl->dol_misc.dol_volume.dol_DiskType = type;
    LockDosList(LDF_VOLUMES | LDF_WRITE);
    ok = AddDosEntry(dl);
    UnLockDosList(LDF_VOLUMES | LDF_WRITE);
    if (!ok) {
        FreeDosEntry(dl);
        return 0;
    }
    for (i = 0; i < 8; i++)
        if (!_dash_hd_vols[i]) {
            _dash_hd_vols[i] = dl;
            break;
        }
    _dash_hd_diskevent(IECLASS_DISKINSERTED);
    return (LONG)dl;
}

static void _dash_hd_vol_remove(LONG vol) {
    struct DosList *dl = (struct DosList *)vol;
    LONG i;
    if (!dl) return;
    for (i = 0; i < 8; i++)
        if (_dash_hd_vols[i] == dl) _dash_hd_vols[i] = NULL;
    LockDosList(LDF_VOLUMES | LDF_WRITE);
    RemDosEntry(dl);
    UnLockDosList(LDF_VOLUMES | LDF_WRITE);
    FreeDosEntry(dl);
    _dash_hd_diskevent(IECLASS_DISKREMOVED);
}

/* ---- the blocks of a device (trackdisk.device, scsi.device...) ---- */
static void _dash_dev_close(LONG h) {
    struct IOExtTD *io = (struct IOExtTD *)h;
    struct MsgPort *mp;
    LONG i;
    if (!io) return;
    for (i = 0; i < 8; i++)
        if (_dash_dev_ios[i] == io) _dash_dev_ios[i] = NULL;
    mp = io->iotd_Req.io_Message.mn_ReplyPort;
    CloseDevice((struct IORequest *)io);
    DeleteIORequest((struct IORequest *)io);
    DeleteMsgPort(mp);
}

static void _dash_dev_cleanup(void) {
    LONG i;
    for (i = 0; i < 8; i++)
        if (_dash_dev_ios[i]) _dash_dev_close((LONG)_dash_dev_ios[i]);
}

static LONG _dash_dev_open(STRPTR name, LONG unit, LONG flags) {
    struct MsgPort *mp;
    struct IOExtTD *io;
    LONG i;
    if (!name || !(mp = CreateMsgPort())) return 0;
    if (!(io = (struct IOExtTD *)CreateIORequest(mp, sizeof(struct IOExtTD)))) {
        DeleteMsgPort(mp);
        return 0;
    }
    if (OpenDevice((CONST_STRPTR)name, unit, (struct IORequest *)io, flags)) {
        DeleteIORequest((struct IORequest *)io);
        DeleteMsgPort(mp);
        return 0;
    }
    if (!_dash_dev_atexit) _dash_dev_atexit = _dash_atexit(_dash_dev_cleanup) == 0;
    for (i = 0; i < 8; i++)
        if (!_dash_dev_ios[i]) {
            _dash_dev_ios[i] = io;
            break;
        }
    return (LONG)io;
}

/* len bytes from block (of bsize bytes) on: up to 4 GB with CMD_READ, beyond with TD64 or NSD */
static LONG _dash_dev_rw(LONG h, LONG block, LONG bsize, LONG buf, LONG len, BOOL write) {
    struct IOExtTD *io = (struct IOExtTD *)h;
    ULONG a = (ULONG)block, b = (ULONG)bsize, lo, hi, mid;
    ULONG ll, lh, hl;
    if (!io || !buf) return -1;
    /* block * bsize in 64 bits, from 16-bit parts (no 64-bit multiply in the runtime) */
    ll = (ULONG)(UWORD)a * (UWORD)b;
    lh = (ULONG)(UWORD)a * (UWORD)(b >> 16);
    hl = (ULONG)(UWORD)(a >> 16) * (UWORD)b;
    mid = (ll >> 16) + (lh & 0xFFFF) + (hl & 0xFFFF);
    lo = (ll & 0xFFFF) | (mid << 16);
    hi = (ULONG)(UWORD)(a >> 16) * (UWORD)(b >> 16) + (lh >> 16) + (hl >> 16) + (mid >> 16);
    io->iotd_Req.io_Data = (APTR)buf;
    io->iotd_Req.io_Length = len;
    io->iotd_Req.io_Offset = lo;
    io->iotd_Req.io_Actual = hi;
    io->iotd_Req.io_Flags = 0;
    io->iotd_Req.io_Command = hi ? (write ? TD_WRITE64 : TD_READ64) : (write ? CMD_WRITE : CMD_READ);
    DoIO((struct IORequest *)io);
    if (hi && io->iotd_Req.io_Error == IOERR_NOCMD) {
        io->iotd_Req.io_Data = (APTR)buf;
        io->iotd_Req.io_Length = len;
        io->iotd_Req.io_Offset = lo;
        io->iotd_Req.io_Actual = hi;
        io->iotd_Req.io_Command = write ? NSCMD_TD_WRITE64 : NSCMD_TD_READ64;
        DoIO((struct IORequest *)io);
    }
    return io->iotd_Req.io_Error;
}

static LONG _dash_dev_actual(LONG h) {
    return h ? (LONG)((struct IOExtTD *)h)->iotd_Req.io_Actual : 0;
}

/* Any command without data (TD_MOTOR, TD_CHANGESTATE, CMD_UPDATE...): io_Error; dev_actual, its io_Actual */
static LONG _dash_dev_cmd(LONG h, LONG cmd, LONG length) {
    struct IOExtTD *io = (struct IOExtTD *)h;
    if (!io) return -1;
    io->iotd_Req.io_Command = cmd;
    io->iotd_Req.io_Length = length;
    io->iotd_Req.io_Data = NULL;
    io->iotd_Req.io_Offset = 0;
    io->iotd_Req.io_Flags = 0;
    DoIO((struct IORequest *)io);
    return io->iotd_Req.io_Error;
}


/* File I/O Runtime Functions */

static LONG _dash_file_size(STRPTR filename) {
    BPTR lock;
    struct FileInfoBlock *fib;
    LONG size = -1;

    lock = Lock(filename, ACCESS_READ);
    if (lock) {
        fib = (struct FileInfoBlock *)AllocDosObject(DOS_FIB, NULL);
        if (fib) {
            if (Examine(lock, fib)) {
                size = fib->fib_Size;
            }
            FreeDosObject(DOS_FIB, fib);
        }
        UnLock(lock);
    }
    return size;
}

static BOOL _dash_file_exists(STRPTR filename) {
    BPTR lock = Lock(filename, ACCESS_READ);
    if (lock) {
        UnLock(lock);
        return TRUE;
    }
    return FALSE;
}

static BOOL _dash_file_copy(STRPTR src, STRPTR dest) {
    BPTR srcFile, destFile;
    UBYTE buffer[4096];
    LONG bytesRead;
    BOOL success = FALSE;

    srcFile = Open(src, MODE_OLDFILE);
    if (!srcFile) return FALSE;

    destFile = Open(dest, MODE_NEWFILE);
    if (!destFile) {
        Close(srcFile);
        return FALSE;
    }

    success = TRUE;
    while ((bytesRead = Read(srcFile, buffer, 4096)) > 0) {
        if (Write(destFile, buffer, bytesRead) != bytesRead) {
            success = FALSE;
            break;
        }
    }

    Close(destFile);
    Close(srcFile);
    return success;
}

static APTR _dash_alloc_buffer(LONG size) {
    return AllocVec(size, MEMF_ANY | MEMF_CLEAR);
}

static void _dash_free_buffer(APTR buffer) {
    if (buffer) FreeVec(buffer);
}

static LONG _dash_file_load(STRPTR filename, APTR buffer, LONG maxsize) {
    BPTR file;
    LONG size, bytesRead = 0;

    size = _dash_file_size(filename);
    if (size < 0 || size > maxsize) return -1;

    file = Open(filename, MODE_OLDFILE);
    if (file) {
        bytesRead = Read(file, buffer, size);
        Close(file);
    }
    return bytesRead;
}

static LONG _dash_file_save(STRPTR filename, APTR buffer, LONG size) {
    BPTR file;
    LONG bytesWritten = 0;

    file = Open(filename, MODE_NEWFILE);
    if (file) {
        bytesWritten = Write(file, buffer, size);
        Close(file);
    }
    return bytesWritten;
}

static UBYTE _dash_buffer_get_byte(APTR buffer, LONG offset) {
    return ((UBYTE *)buffer)[offset];
}

static void _dash_buffer_set_byte(APTR buffer, LONG offset, UBYTE value) {
    ((UBYTE *)buffer)[offset] = value;
}

static UWORD _dash_buffer_get_word(APTR buffer, LONG offset) {
    UBYTE *p = (UBYTE *)buffer + offset;
    return (p[0] << 8) | p[1];  /* Big-endian */
}

static void _dash_buffer_set_word(APTR buffer, LONG offset, UWORD value) {
    UBYTE *p = (UBYTE *)buffer + offset;
    p[0] = (value >> 8) & 0xFF;
    p[1] = value & 0xFF;
}

static ULONG _dash_buffer_get_long(APTR buffer, LONG offset) {
    UBYTE *p = (UBYTE *)buffer + offset;
    return (p[0] << 24) | (p[1] << 16) | (p[2] << 8) | p[3];  /* Big-endian */
}

static void _dash_buffer_set_long(APTR buffer, LONG offset, ULONG value) {
    UBYTE *p = (UBYTE *)buffer + offset;
    p[0] = (value >> 24) & 0xFF;
    p[1] = (value >> 16) & 0xFF;
    p[2] = (value >> 8) & 0xFF;
    p[3] = value & 0xFF;
}

/* A C float (IEEE single, big-endian as the 68k keeps it), byte by byte: the offset may be odd */
static void _dash_buffer_set_float(APTR buffer, LONG offset, float value) {
    union { float f; UBYTE b[4]; } u;
    UBYTE *p = (UBYTE *)buffer + offset;
    u.f = value;
    p[0] = u.b[0];
    p[1] = u.b[1];
    p[2] = u.b[2];
    p[3] = u.b[3];
}

static double _dash_buffer_get_float(APTR buffer, LONG offset) {
    union { float f; UBYTE b[4]; } u;
    UBYTE *p = (UBYTE *)buffer + offset;
    u.b[0] = p[0];
    u.b[1] = p[1];
    u.b[2] = p[2];
    u.b[3] = p[3];
    return (double)u.f;
}

static void _dash_buffer_copy(APTR dest, LONG dest_offset, APTR src, LONG src_offset, LONG length) {
    CopyMem((UBYTE *)src + src_offset, (UBYTE *)dest + dest_offset, length);
}

static void _dash_buffer_fill(APTR buffer, LONG offset, LONG length, UBYTE value) {
    UBYTE *p = (UBYTE *)buffer + offset;
    LONG i;
    for (i = 0; i < length; i++) p[i] = value;
}



/* Struct Definitions */

typedef struct _Dash_Listing _Dash_Listing;
