/* @amiga struct: the layout of the 68000 (32-bit pointers: an address in a ULONG) */
static __inline__ ULONG _dash_a32(_DashUP p) {
#ifdef _DASH_DASHOS
    if (p >> 32) _dash_fail("puntero de Amiga de 4 GB o m\341s", NULL);
#endif
    return (ULONG)p;
}
/* the memory of the Amiga is big-endian: a little-endian program turns the bytes of Word and Long */
#if defined(_DASH_DASHOS) && __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
#define _DASH_BE16(x) __builtin_bswap16(x)
#define _DASH_BE32(x) __builtin_bswap32(x)
#else
#define _DASH_BE16(x) (x)
#define _DASH_BE32(x) (x)
#endif
